// client-ordering · кейсы co-01…co-04, co-17 (.qa/tests/client-ordering/) — קטלוג הלקוח
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/buyer.json') });

const counter = (page: Page) => page.getByText(/^\d+ מוצרים$/);
const countOf = async (page: Page) => Number((await counter(page).innerText()).match(/\d+/)![0]);

test.describe('client-ordering — קטלוג: גלישה, חיפוש וסינון', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/shop');
    await expect(page.getByRole('searchbox', { name: 'חיפוש מוצר' })).toBeVisible();
    await expect(page.locator('article').first()).toBeVisible();
  });

  test('קטלוג מאורגן בקטגוריות עם מחירון אישי #6a38cf5e @prod-safe', async ({ page }) => {
    await expect(page.getByRole('button', { name: 'הכל', exact: true })).toHaveAttribute('aria-pressed', 'true');
    await expect(page.getByRole('button', { name: 'מצתים', exact: true })).toBeVisible();
    await expect(page.getByText('כל המוצרים')).toBeVisible();
    expect(await countOf(page)).toBeGreaterThan(0);
    await expect(page.getByText('המחירון האישי שלך')).toBeVisible();
    await expect(page.getByText('כל המחירים כאן הם המחירים שסוכמו עבורך')).toBeVisible();
    await expect(page.locator('article').first()).toContainText('₪');
  });

  test('חיפוש מסנן בזמן אמת; אין תוצאות → מצב ריק ו«נקה סינון» #6a38cf5e @prod-safe', async ({ page }) => {
    const total = await countOf(page);
    const search = page.getByRole('searchbox', { name: 'חיפוש מוצר' });

    await search.fill('פרלמנט');
    await expect(counter(page)).toBeVisible({ timeout: 15_000 });
    await expect.poll(() => countOf(page), { timeout: 15_000 }).toBeLessThan(total);
    await expect(page.locator('article').first()).toBeVisible({ timeout: 15_000 });
    const names = await page.locator('article').allInnerTexts();
    expect(names.length).toBeGreaterThan(0);
    for (const n of names) expect(n).toContain('פרלמנט');

    await search.fill('QA-NO-SUCH-XYZ');
    await expect(page.getByText('לא נמצאו מוצרים תואמים')).toBeVisible();
    await expect(page.getByText('נסה חיפוש אחר או נקה את הסינון')).toBeVisible();
    await expect(page.getByText('0 מוצרים')).toBeVisible();

    await page.getByRole('button', { name: 'נקה סינון' }).click();
    await expect(search).toHaveValue('');
    await expect.poll(() => countOf(page)).toBe(total);
  });

  test('סינון לפי קטגוריה מציג רק את מוצרי הקטגוריה #6a38cf5e @prod-safe', async ({ page }) => {
    const total = await countOf(page);
    const chip = page.getByRole('button', { name: 'מצתים', exact: true });
    await chip.click();
    await expect(chip).toHaveAttribute('aria-pressed', 'true');
    await expect(page.getByText('מצתים', { exact: true }).last()).toBeVisible();
    await expect.poll(() => countOf(page)).toBeLessThan(total);

    await page.getByRole('button', { name: 'הכל', exact: true }).click();
    await expect(page.getByText('כל המוצרים')).toBeVisible();
    await expect.poll(() => countOf(page)).toBe(total);
  });

  test('מונה המוצרים: קטגוריה עם מוצר יחיד — «מוצר אחד», «הכל» — «N מוצרים», אין «1 מוצרים» #6fcb020f @desktop @prod-safe', async ({ page }) => {
    await expect(counter(page)).toBeVisible(); // «הכל» — «N מוצרים»
    expect(await countOf(page)).toBeGreaterThan(1);
    // на 05.10 в «מבחנות» и «אלקטרונית» — по одному товару
    let checked = 0;
    for (const name of ['מבחנות', 'אלקטרונית']) {
      const chip = page.getByRole('button', { name, exact: true });
      if (!(await chip.count())) continue;
      await chip.click();
      await expect(chip).toHaveAttribute('aria-pressed', 'true');
      const single = page.getByText('מוצר אחד', { exact: true });
      await expect(single.or(counter(page)).first()).toBeVisible({ timeout: 15_000 });
      await expect(page.getByText('1 מוצרים', { exact: true })).toHaveCount(0);
      if (await single.count()) {
        await expect(page.locator('article')).toHaveCount(1, { timeout: 15_000 });
        checked++;
      } else {
        expect(await countOf(page), `«${name}»: N מוצרים только для 0 или 2+`).not.toBe(1);
      }
    }
    test.info().annotations.push({ type: '#6fcb020f', description: `категорий с одним товаром проверено: ${checked}` });
    await page.getByRole('button', { name: 'הכל', exact: true }).first().click();
    await expect(page.getByText('כל המוצרים')).toBeVisible();
    await expect(counter(page)).toBeVisible();
  });

  test('קטלוג גדול נטען בהדרגה בגלילה #6a38cf5e @desktop @prod-safe', async ({ page }) => {
    const total = await countOf(page);
    const first = await page.locator('article').count();
    expect(first).toBeLessThan(total);
    for (let i = 0; i < 4; i++) {
      await page.mouse.wheel(0, 20000);
      await page.waitForTimeout(700);
    }
    await expect.poll(() => page.locator('article').count()).toBeGreaterThan(first);
  });
});
